import map from "@/data/joma-tile-images.json";

/**
 * Exact folder-tile pictures from the Joma B2B portal (joma-sport.net),
 * hosted unedited in `public/joma-tiles/`. Generated by
 * `scripts/map-joma-tiles.ts`; keys are `folder:<joma folder key>` or
 * `landing:<page>:<tile label>`.
 */
const TILE_IMAGES = map as Record<string, string>;

export function jomaFolderTileImage(folderKey: string) {
  return TILE_IMAGES[`folder:${folderKey}`] ?? "";
}

export function jomaLandingTileImage(page: string, label: string) {
  return TILE_IMAGES[`landing:${page}:${label}`] ?? "";
}
